export const LESSONS=[
{id:'founder',group:'理解游戏',title:'角色与能力：不同起点，同一条创业路',desc:'岗位、资金、四项能力如何影响选择。',image:'current-careers.png',goals:['理解职业差异，而不把职业当成固定路线','区分启动资金与原月薪目标'],features:['开发、产品、运营、销售四个职业；性别决定形象，不改变经济数值。','四项能力为交付能力、客户洞察、内容创作、拓客沟通，均可成长至 100。'],logic:'职业提供非对称起点，让玩家有理由尝试不同策略；能力可以成长，避免开局选择锁死后续玩法。资金决定缓冲期，原月薪决定成就门槛，二者承担不同作用。',flow:['选择岗位','确认形象与公司名','设定原月薪','生成能力与旧识','开始经营'],rules:['初始能力总和均为 190，优势能力为 80。','开发 / 产品 / 运营 / 销售的启动资金分别为 18,000 / 20,000 / 14,000 / 22,000 元。','原月薪为游戏目标，允许 3,000–50,000 元整数，开局后锁定；职业默认值不是现实薪资统计。'],edge:'能力总点数相同并不意味着实际难度完全一致。现金、人脉和不同动作的回报会共同影响平衡。',source:['dist/engine.js · BACKGROUNDS / initial / effects','dist/progression.js · SALARY_PRESETS / initJourney'],question:'选择女性创始人会怎样影响经营？',options:['只改变形象，不改变能力与经济数值','提高内容创作能力','降低启动资金'],answer:0,explain:'角色形象与经济规则分开，让外观选择不承担隐藏的数值惩罚。',step:7},
{id:'workspace',group:'理解游戏',title:'工作位：把系统菜单变成生活场景',desc:'微信、Agent、公众号与桌面日程的空间表达。',image:'current-workstation.png',goals:['辨认场景中的功能入口','理解打开工具与执行工作之间的区别'],features:['微信对应客户沟通；Agent 对应研发与交付；公众号对应内容获客。','经营状态、能力、日程与创业之路被整合到工作位图中，日程可拖动并保存位置。'],logic:'用熟悉的软件和物件承载抽象经营动作，降低学习入口的成本。场景负责让人知道去哪里，具体操作仍由弹窗表单和规则引擎完成。',flow:['看到状态或任务','打开对应工具','查看方案与代价','确认执行','状态与日程更新'],rules:['打开工具本身不消耗行动次数；确认执行工作才消耗时段。','每天最多两次工作行动，每次按 8 小时计。','日程位置是界面偏好，不会改变事项的真实到期时间。'],edge:'写实背景可能造成按钮与信息的辨识问题。入口需要语义标签、足够对比度，关键数据不能只存在于背景图里。',source:['dist/app.js · desktopApps / openWorkspace / integrateDeskHUD / installScheduleDrag','dist/style.css · 工作位与日程样式'],question:'拖动日程表到另一侧，会改变交付日期吗？',options:['会顺延一天','不会，只改变显示位置','会消耗一个时段'],answer:1,explain:'位置属于界面状态，到期日属于游戏状态，两者独立。',step:36},
{id:'network',group:'客户与交付',title:'人脉与获客：联系人不等于订单',desc:'旧识、主动拓客和内容咨询的三种来源。',image:'current-contacts.png',goals:['区分联系人、合作意愿与合同','理解开局人脉和后续获客渠道'],features:['新局按职业给开发 5、产品 7、运营 8、销售 10 位旧识。','旧识来自主角过去的人脉；初始没有已签订单。主动拓客使用有限人脉池，内容营销可产生咨询。'],logic:'先提供可以行动的联系对象，避免开局空白；同时保留沟通与交付环节，让关系成为机会而不是自动发放收入。',flow:['获得联系人','了解行业与岗位','沟通需求','获得合作意愿','签约'],rules:['主动拓客每时段最多获得 1 + floor(拓客沟通 / 30) 条线索，还受剩余池和 12 人容量限制。','初始主动拓客池分别为 4 / 6 / 8 / 12；它与 5–10 位开局旧识不是同一个数量。','旧存档不会强行重新生成一套旧识。'],edge:'通讯录容量和线索有效期会限制继续拓客。现有旧存档可能保留早期的重复联系人，不应把补拍图当成新局种子名单。',source:['dist/contacts.js · STARTER_NETWORK / CONTACTS','dist/engine.js · makeLead / workActions'],question:'销售开局的 10 位旧识意味着什么？',options:['10 个已付款订单','可以联系的熟人，仍需沟通与签约','10 次免费交付'],answer:1,explain:'人脉是进入沟通的入口，不是已经完成的交易。',step:29},
{id:'conversation',group:'客户与交付',title:'客户对话：模型给反馈，规则管成交',desc:'匹配度、决策权和熟悉度为何共同约束签约。',image:'current-contacts.png',goals:['理解 LLM 输出与游戏判定的边界','识别为什么高分回复仍可能不成交'],features:['DeepSeek 扮演客户、评价沟通，给出 converted / followup / rejected。','服务端结合能力匹配度、决策能力、熟悉度和评分决定是否开放合作意愿。'],logic:'语言模型适合生成自然反馈，但不能让一句“我同意”绕过经营条件。确定性的门槛给结果提供边界和可测试性。',flow:['玩家发送内容','服务端校验输入','模型回复与评分','关系规则复核','更新客户状态'],rules:['转化需模型同意合作，且能力匹配度 ≥40、决策能力 ≥55、熟悉度 ≥35、总分 ≥70。','任何一个条件不足，converted 会被降为 followup。','聊天本身不额外扣时；签约是之后单独确认的动作。'],edge:'决策能力目前是客户档案里的固定参数。与权限不足的人反复聊天不能提升其职权，当前实现也没有自动转介绍给负责人的完整机制。',source:['llm.mjs · evaluate / validateChat','customer-rules.mjs · customerContext / judgeOpportunity','dist/engine.js · applyConversation'],question:'模型给了 90 分并同意合作，但对方决策能力只有 25，会发生什么？',options:['立即签约收钱','扣除开发费用','保留跟进状态，不能仅凭高分签约'],answer:2,explain:'决策能力门槛不能被高沟通评分替代。',step:10},
{id:'crm',group:'客户与交付',title:'SCRM：把对话变成可管理的进度',desc:'线索、合作、反馈与承诺如何放在同一个入口。',image:'history-8.png',goals:['区分客户状态和项目状态','理解为什么需要跨页面的客户视图'],features:['按新线索、跟进中、待签约、合作中与暂不合作筛选。','展示最近反馈、来源、相关 Demo 承诺，并跳转微信或 Agent。'],logic:'微信适合进行一段对话，SCRM 适合回答“谁需要跟进、谁已经合作”。它是对现有数据的组织视图，而不是另一套独立客户数据库。',flow:['查看客户列表','按阶段筛选','识别下一步','进入微信或交付','返回查看进度'],rules:['查看和筛选 SCRM 不扣时间。','合作意愿明确不等于已签约；签约后进入项目阶段。','Demo 承诺在未签约时也可以形成客户任务。'],edge:'同一客户在多个阶段的记录应保留来源和关联，不能把“任务完成”和“成交”混为一谈。',source:['dist/app.js · openSCRM','dist/engine.js · clientTasks / registerClientPromise'],question:'SCRM 中“待签约”的客户是否已经产生正式交付项目？',options:['还没有，需要确认签约','已经完成交付','已经收到全款'],answer:0,explain:'合作意愿、签约、交付是三个不同状态。',step:28},
{id:'delivery',group:'客户与交付',title:'签约与交付：把承诺兑现为现金',desc:'预付款、标准工时、尾款与违约的闭环。',image:'history-3.png',goals:['区分耗用时段和完成的标准工作量','理解首单里程碑为什么需要完整付款证据'],features:['签约支付 30% 预付款，完整交付后支付 70% 尾款。','交付可指定项目，完成后进入项目库；承诺的客户 Demo 另有任务。'],logic:'分期收款让合同既提供现金缓冲，也留下履约责任。只有完整交付才释放尾款，迫使玩家在继续接单与兑现承诺之间分配时间。',flow:['签约收预付款','安排交付','能力与精力决定产出','完成交付收尾款','归档作品与点亮成就'],rules:['每时段标准产出 = 4 + floor(交付能力 / 10)，组件库额外 +2。','精力低于 45 时效率为 75%，低于 25 时为 50%；实际工作量向下取整。','最多同时 3 个项目。项目逾期信誉 -8，两周后仍未完成会取消并退预付款。'],edge:'客户 Demo 是验证方案的原型，不会自动完成正式合同，也不会直接触发首单全款成就。',source:['dist/engine.js · accept / deliver / effects / completeClientDemo','dist/progression.js · updateJourney'],question:'交付能力 80、精力充足、无组件库，一次交付完成多少标准工时？',options:['8 小时','12 小时','80 小时'],answer:1,explain:'4 + floor(80 / 10) = 12；消耗的仍是一个 8 小时行动时段。',step:21},
{id:'product',group:'产品与增长',title:'产品与 Demo：从想法到可售卖方案',desc:'方向、用户、场景、解决方式和价格的验证。',image:'current-product.png',goals:['区分 Demo 完成和正式上线','理解研究匹配度为何不能替代方案评估'],features:['玩家定义五项产品信息，模型评估转化价值和用户匹配度。','成功生成 Demo 消耗一个时段与 300 元，原型进入项目库，后续继续研发到 100%。'],logic:'把“想做什么”与“有没有人愿意买”同时放进立项环节。原型提供可以展示的成果，而研发进度保留从演示到上线的成本。',flow:['定义方案','评估并生成 Demo','成功后扣资源','继续研发','上线后次日销售'],rules:['模型评估的转化价值与初始匹配度都要 ≥60，才有变现资格。','调研提高运营匹配度，但不会替换不合格的原始评估分数。','重做方案会重置当前产品进度、销量和连续销售记录，旧 Demo 仍保留在作品库。'],edge:'生成失败时不能先扣除游戏资源。页面所展示的可交互 Demo 不是已经部署的真实商业产品。',source:['product-llm.mjs · evaluateProduct / developDemo','dist/engine.js · confirmProduct / completeDemo / projectLibrary'],question:'Demo 已生成，但研发进度 34%，能自动出售吗？',options:['能，已经有页面','只要价格低就能','不能，仍需研发至 100% 且评估合格'],answer:2,explain:'原型可展示，不代表产品已经上线并满足销售条件。',step:12},
{id:'marketing',group:'产品与增长',title:'内容营销：让质量影响真实结果',desc:'相关性、实用性、可信度如何改变触达与咨询。',image:'history-5.png',goals:['理解文章评分的三个维度','区分内容触达、咨询和实际收入'],features:['公众号文章交给 LLM 独立评价，而不是依照选项位置直接决定好坏。','反馈影响触达、咨询数和信誉；实际发布消耗一个行动时段。'],logic:'同样的一次行动应因内容质量而得到不同回报，鼓励玩家理解目标用户，而不只是机械点击发布。',flow:['选择或撰写文章','评估三个维度','确认合法结果','扣行动时段','增加触达与咨询'],rules:['综合质量 = 相关性×0.4 + 实用性×0.35 + 可信度×0.25，四舍五入。','可信度低于 35 会降低信誉；高质量且高可信的文章可提高信誉。','咨询数受评分门槛与通讯录剩余容量限制；增加触达不等于立即收钱。'],edge:'高相关但空泛的硬销内容不应获得高实用分。模型输出仍需要字段校验，失败时不能当成成功营销。',source:['marketing-llm.mjs · evaluateMarketing','dist/engine.js · marketingOutcome / workActions','dist/app.js · publishMarketing'],question:'一篇文章带来了 2 条咨询，是否已经产生 2 笔订单收入？',options:['不是，咨询还需要沟通与签约','是，立即收取全款','是，直接完成项目'],answer:0,explain:'触达、咨询、成交和收款分别属于不同环节。',step:25},
{id:'sales',group:'产品与增长',title:'自动销售：从卖工时到卖产品',desc:'需求小数累积、定价弹性和每日实际到账。',image:'current-product.png',goals:['理解为什么高价不一定带来高收入','区分预期需求与当天整数订单'],features:['合格产品上线后，从次日开始在日结时自动成交，无需逐单聊天。','触达、匹配度、转化价值、信誉与售价共同决定需求，需求余数留到后续日期。'],logic:'产品收入应可脱离玩家每单的沟通和交付动作。用价格弹性和需求余数限制极端定价，同时让低流量阶段仍有缓慢成交的可能。',flow:['积累流量','计算每日需求','累加不足一单的余数','成交整数订单','入账并记录连续销售'],rules:['每日需求 = 触达/120 × 匹配度/100 × 转化价值/100 × (0.8+信誉/100) ÷ (1+(售价/199)²)。','售价 199 元是游戏弹性基准，不是强制定价。','周结算不会把已经结算过的每日订单再发一遍。'],edge:'当前把累计触达作为持续流量来源，没有完整模拟客户流失、续费或商品退款概率。这是简化的经营模型。',source:['dist/progression.js · productDemand','dist/engine.js · settleProductDay / nextDay / advance'],question:'单日需求是 0.4，为什么不代表这一天就到账 0.4 份的钱？',options:['需求是无效数字','当天只成交整数订单，余数累计','系统会自动补成一单'],answer:1,explain:'需求累积与实际成交分开，小数不能直接变成现金。',step:39},
{id:'growth',group:'经营与成长',title:'资料、学习与工具：用今天换明天的效率',desc:'调研提升匹配度，训练补短板，工具扩大产能。',image:'current-workstation.png',goals:['区分产品匹配度与个人能力','理解购买工具的收益与持续成本'],features:['看资料提升产品需求匹配度，学习笔记允许选择四项能力之一训练。','可复用组件库和自动化工作流，分别提供单次交付增益与每周项目推进。'],logic:'把立即赚钱与长期投入放进同一份日程，形成机会成本。能力改善多个后续动作，产品匹配度直接影响销售，工具则把现金转换为产能。',flow:['识别当前瓶颈','选择调研、训练或工具','投入时段或现金','观察后续效率变化'],rules:['每次调研提高 4 + floor(客户洞察 / 5) 点产品匹配度，上限 100。','每次专项学习提升所选能力 4 点，上限 100。','组件库购买价 2,200 元，每个交付时段增加 2 标准小时；自动化工作流购买价 1,800 元，每周推进 4 标准小时，并产生 120 元周费。'],edge:'提高当前产品匹配度不能替代初始方案评估的销售门槛。工具需要足够订单消化产能，购买并不保证回本。',source:['dist/engine.js · effects / workActions / TOOLS'],question:'学习笔记主要改变哪一项？',options:['所选择的个人能力','直接获得一笔订单','自动清除逾期记录'],answer:0,explain:'训练提升能力，随后通过行动效率影响经营；它不会直接发放订单或取消违约。',step:16},
{id:'schedule',group:'经营与成长',title:'日程与精力：机会成本具体化',desc:'每天两件事，交付和约定会过期。',image:'history-9.png',goals:['理解为什么不能无限工作','区分日程违约与项目逾期'],features:['每天两个工作时段，未用时段不能结转。','到期约定与正式项目各自有逾期规则；休息与日末恢复影响精力。'],logic:'有限时间迫使玩家排序；可见的交付日期把长期责任变成当天决策。惩罚用于让承诺有成本，而不是仅作为装饰。',flow:['检查今日约定','分配两个时段','执行与休息','结束今天','检查违约与每日收款'],rules:['普通约定未按时完成会信誉 -5，并扣约定赔付金额（若有）。','项目逾期按项目规则处理，不与普通约定规则混用。','休息行动恢复 18 点精力；日末还会恢复，空闲时段影响恢复量。'],edge:'完成一个客户 Demo 不代表已经发给客户；带有发送期限的承诺要追踪“已发送”状态。',source:['dist/engine.js · addAppointment / fulfillAppointment / nextDay / markClientDemoSent','dist/app.js · calendarPanel / endToday'],question:'今天只用一个时段，明天是否有三个时段？',options:['是','只有销售职业可以','不是，明天仍最多两件事'],answer:2,explain:'时间不累积；空闲会参与精力恢复，但不变成明天的工作槽。',step:17},
{id:'finance',group:'经营与成长',title:'财务与榜单：用正确口径看成绩',desc:'余额、收入、利润和客户数分别说明什么。',image:'current-finance.png',goals:['分清初始资金、营业收款和利润','理解排行榜为什么需要公开统计口径'],features:['财务情况展示账户余额、收支和待收尾款。','排行榜按收入、利润、客户、交付、销量、信誉分别排序。'],logic:'余额回答“还能活多久”，收入回答“卖出了多少”，利润回答“扣掉支出后剩多少”。只显示单一数字容易让玩家误判经营质量。',flow:['发生交易','记入账单与累计指标','更新余额','按指标排序','比较经营结果'],rules:['余额 = 启动资金 + 累计收入 - 累计支出。每周基础支出 850 元。','榜单利润采用收付口径，即累计收入减累计支出，不是会计权责发生制利润。','客户榜按合作中及已交付项目的客户名去重，不把潜客和未签约 Demo 算客户。'],edge:'当前榜单只比较本机浏览器中的存档，并非联网排行榜。不同职业、经营时间和月薪目标会影响比较公平性。',source:['dist/engine.js · money','dist/leaderboard.js · RANK_METRICS / rankCompanies','dist/app.js · finance / openLeaderboard'],question:'玩家启动资金 20,000 元，还没有交易，收入榜应显示多少？',options:['20,000 元','0 元','按原月薪显示'],answer:1,explain:'本金不是收入；榜单不把开局资金当成经营成绩。',step:35},
{id:'journey',group:'经营与成长',title:'五个里程碑：让成长有明确方向',desc:'首单全款、工资替代与持续收入的证据链。',image:'history-15.png',goals:['掌握五阶段的顺序与时间窗口','识别一次性高收入和可持续收入的区别'],features:['首单收齐全款 → 月到账达到原薪 → 连续 7 天自动成交 → 连续 28 天自动收入超过原薪 → 达到原薪两倍。','工作位追踪当前任务，达成后保留勋章，最终展示胜利证据。'],logic:'任务链把创业的抽象成功拆成可检查的阶段：先证明有人愿意买，再证明可以替代工资，最后证明产品能持续自行成交。',flow:['完成首单','证明月度收入','验证产品 MVP','替代原工资','持续收入翻倍'],rules:['第二阶段按任意一个 28 天创业月的经营到账判断；启动资金不计入，退款扣回。','第四阶段严格“超过”原月薪，第五阶段“达到”两倍即可；都要求同一产品连续 28 天每天有销售。','阶段顺序不可跳过；第 52 周结束未完成目标不算胜利，余额为负则破产。'],edge:'旧版按周记录的销量不能推断为每日持续收入。换产品会重置当前连续记录，但已获勋章保留。',source:['dist/progression.js · journeyStatus / updateJourney / migrateJourney','tests/journey.test.mjs · 边界与整局模拟'],question:'单笔产品销售赚到原工资三倍，可以直接通关吗？',options:['不可以，还需顺序成就和连续 28 天销售','可以，高于两倍就行','只要余额非负就可以'],answer:0,explain:'胜利验证的是持续产品收入，而非某一笔金额。',step:39},
{id:'simple',group:'系统与实现',title:'简单模式：减少输入，不取消判断',desc:'三选一如何保留策略差异与确认步骤。',image:'history-4.png',goals:['理解生成、选择、执行的三个阶段','知道简单模式为何仍然需要评估实际内容'],features:['简单模式由 LLM 生成三个可选方案；仿真模式允许自己输入。','选项可展开完整内容，选择后仍需确认发送或执行。'],logic:'降低写作负担，让玩家把注意力放在决策上。选项应该有质量差异，但不能只按 A/B/C 的位置预设奖励。',flow:['生成三个方案','查看完整内容','选择一个','确认行动','独立评估并结算'],rules:['生成选项不扣游戏时间或资金，但远程调用可能消耗 API 额度。','未选方案不能直接执行；选择本身也不会发送或扣费。','姓名与工资这类身份或目标设置保留独立输入，不由行动选项代填。'],edge:'隐藏输入框仍会触发表单校验，必须给玩家可理解的错误提示，不能把字段 ID 显示成游戏反馈。',source:['choices.mjs · CHOICE_FIELDS / generateChoices','dist/app.js · installSimpleChoices / generateSimpleChoices'],question:'点击一个简单模式选项后，系统应当立即扣费并发送吗？',options:['应该','只有 A 选项会','不应，仍要确认执行'],answer:2,explain:'生成和选择都不是最终执行步骤。',step:22},
{id:'architecture',group:'系统与实现',title:'本地架构：界面、规则、模型各司其职',desc:'存档隔离、模型失败与可重复测试的边界。',image:'current-admin.png',goals:['理解本地服务如何调用 DeepSeek','知道多用户系统与账号认证的区别'],features:['浏览器界面与规则引擎处理游戏；本地 Node 服务负责配置和模型请求。','创业者使用不同存档键；密钥保存在本地服务配置中，不进入游戏存档。'],logic:'把可确定的经济规则与非确定的语言反馈分开，能在模型失败时保护游戏资源，也能用固定模型结果测试完整经营流程。',flow:['界面提交输入','本地服务校验','DeepSeek 生成结果','校验结构与业务门槛','规则引擎提交状态'],rules:['服务只绑定本机地址，API 需要请求头和来源检查。','本地角色没有密码或服务端登录；同一浏览器共享本机模型配置。','HTML 文件版与 HTTP 服务版属于不同存储环境，存档不自动互通。'],edge:'本地存档不是防作弊系统。固定 LLM 结果的整局测试能验证规则链路，却不能代替真实模型的长期体验和游戏平衡测试。',source:['server.mjs · 路由 / 请求校验 / busy 锁','llm.mjs · completion / 配置与输出校验','dist/users.js · loadUsers / userSaveKey','tests/ · 单元、回归与固定结果整局测试'],question:'不同本地创业者是否拥有独立的 DeepSeek 密钥配置？',options:['没有，使用本机服务的共享配置','有，每人一个远程账号','密钥直接存在每人的存档里'],answer:0,explain:'角色存档隔离与服务配置隔离是两回事，当前实现只隔离前者。',step:9}
];
